const VIEW = { full: "0 0 1024 1024", header: "154.9 174.4 835.1 835.1" };

/**
 * The mark, as the contract reads it. Rest is not still: the mark drifts, slowly enough that you see
 * it if you rest your eye on it and not if you look past it. Loading is the same orbit and the same
 * keyframes at 27x the rate, and its accents at full chroma. Every duration and delay in the
 * stylesheet is a fixed fraction of `--cm-turn`, so every `cm-` animation is paced by it.
 */
const SPEC: Omit<MarkSpec, "id"> = {
  beads: 8,
  paced: /^cm-/,
  liveClass: "cm-live",
  look: {
    rest: { "--cm-a1": "oklch(0.698 0.127 295)", "--cm-a2": "oklch(0.711 0.134 340)" },
    live: { "--cm-a1": "oklch(0.74 0.16 295)", "--cm-a2": "oklch(0.75 0.17 340)" },
  },
  accents: ["--cm-a1", "--cm-a2"],
  turnVar: "--cm-turn",
  paperVar: "--cm-paper",
  view: VIEW,
};

export type CollieMarkProps = MarkProps;

/**
 * A mark of the Collie family: this ring, these beads, this stylesheet and this motion, with
 * `head` as its dog. The Collie mark is one; the coat variants (`collie-collar-mark.tsx`,
 * `collie-blaze-mark.tsx`) are the others, and each of those files is only its head. The family
 * shares ONE stylesheet, byte for byte, so two of its marks on one page define every `cm-` name
 * identically and cannot disagree.
 */
export function collieFamilyMark(id: string, head: string): ComponentType<CollieMarkProps> {
  const spec: MarkSpec = { ...SPEC, id };
  const bodies = { full: BODY.full[0] + head + BODY.full[1], header: BODY.header[0] + head + BODY.header[1] };
  function FamilyMark(props: CollieMarkProps) {
    const m = useMark(spec, props);
    /*
     * THE WHOLE `{ __html }` OBJECT IS MEMOISED, not just the string inside it.
     *
     * React 19 diffs `dangerouslySetInnerHTML` by the IDENTITY of that object and no longer compares
     * the `__html` value. A fresh literal per render is therefore a fresh prop every render, and the
     * DOM update it schedules is `node.innerHTML = html` — unconditional. The markup comes out
     * byte-identical and every child is still destroyed and rebuilt, which restarts all thirty-seven
     * CSS animations at zero.
     *
     * That is invisible while loading and ruinous at rest. In Collie something re-renders the header
     * about every 1.5 seconds; at the 1.8s rate a restart that often is a small stutter, but at
     * 48s it means the orbit replays the first three per cent of its turn forever and never
     * reaches the rest. It reads exactly like a short animation stuck on a loop, because it is one.
     *
     * So the object is built once per instance and passed by reference. React then sees the same prop
     * it saw last time, writes nothing, and the animations run for as long as the mark is mounted.
     *
     * Every gradient and mask id is finished here too, with the instance's `uid`: an id inside an
     * inline SVG is DOCUMENT-scoped, so a header mark and a splash mark on one page would otherwise
     * name the same mask and one would win.
     */
    const body = useMemo(
      () => ({ __html: bodies[m.weight].replaceAll("__cmid__", `cm${m.uid}-`) }),
      [m.weight, m.uid],
    );
    // The pace, the phase carry across a change and the public variables: see useMark in
    // mark-contract.ts. The resting class goes on the body group, because the root's class is the
    // caller's to own; both select the same keyframes.
    return (
      <svg {...m.root}>
        <style>{STYLE}</style>
        <g className={m.live ? undefined : "cm-drift"} dangerouslySetInnerHTML={body} />
      </svg>
    );
  }
  return FamilyMark;
}

export const CollieMark = collieFamilyMark("collie", HEAD);
